import{_ as t,o as a,c as e,Q as d}from"./chunks/framework.48927342.js";const u=JSON.parse('{"title":"Making a Hospital Appointment","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/dialogues/01-hospital-appointment.md","filePath":"en/more/maltese/practice/dialogues/01-hospital-appointment.md"}'),n={name:"en/more/maltese/practice/dialogues/01-hospital-appointment.md"},o=d('<h1 id="making-a-hospital-appointment" tabindex="-1">Making a Hospital Appointment <a class="header-anchor" href="#making-a-hospital-appointment" aria-label="Permalink to &quot;Making a Hospital Appointment&quot;">​</a></h1><p><strong>Scenario:</strong> David calls the health centre to book a doctor&#39;s appointment with receptionist Maria and confirm the time and required documents.</p><h2 id="complete-dialogue" tabindex="-1">Complete Dialogue <a class="header-anchor" href="#complete-dialogue" aria-label="Permalink to &quot;Complete Dialogue&quot;">​</a></h2><p><strong>Maria:</strong> Bonġu, Ċentru tas-Saħħa. Kif nista&#39; ngħinek?</p><p><strong>David:</strong> Bonġu. Nixtieq nagħmel appuntament mat-tabib, jekk jogħġbok.</p><p><strong>Maria:</strong> Għandek preferenza għal xi ġurnata?</p><p><strong>David:</strong> Jekk jista&#39; jkun, għada filgħodu.</p><p><strong>Maria:</strong> Għandna ħin fl-għaxra u nofs. Tajjeb għalik?</p><p><strong>David:</strong> Iva, tajjeb ħafna. Għandi bżonn inġib xi dokumenti?</p><p><strong>Maria:</strong> Ġib il-karta tal-identità u l-karta tas-saħħa.</p><p><strong>David:</strong> Grazzi. Narak għada.</p><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><h3 id="_1-maria-receptionist" tabindex="-1">1. Maria (Receptionist) <a class="header-anchor" href="#_1-maria-receptionist" aria-label="Permalink to &quot;1. Maria (Receptionist)&quot;">​</a></h3><p><strong>Malti:</strong> Bonġu, Ċentru tas-Saħħa. Kif nista&#39; ngħinek?</p><p><strong>Translation:</strong> Good morning, Health Centre. How can I help you?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Bonġu</td><td>hello; good morning</td><td>Common greeting</td></tr><tr><td>Ċentru</td><td>centre</td><td>Masculine noun</td></tr><tr><td>tas-Saħħa</td><td>of health; health</td><td>Contracted form of <code>ta&#39; + is-saħħa</code>; together, “Health Centre”</td></tr><tr><td>Kif</td><td>how</td><td>Question word</td></tr><tr><td>nista&#39;</td><td>I can</td><td>First-person marker <code>n-</code>; <code>jista&#39;</code> means “can/be able”</td></tr><tr><td>ngħinek</td><td>help you</td><td><code>ngħin</code> “I help” + <code>-ek</code> “you”</td></tr></tbody></table><h3 id="_2-david-patient" tabindex="-1">2. David (Patient) <a class="header-anchor" href="#_2-david-patient" aria-label="Permalink to &quot;2. David (Patient)&quot;">​</a></h3><p><strong>Malti:</strong> Bonġu. Nixtieq nagħmel appuntament mat-tabib, jekk jogħġbok.</p><p><strong>Translation:</strong> Good morning. I would like to make an appointment with the doctor, please.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Bonġu</td><td>hello; good morning</td><td>Greeting</td></tr><tr><td>Nixtieq</td><td>I would like</td><td>Polite expression of a wish</td></tr><tr><td>nagħmel</td><td>I do; I make; I arrange</td><td><code>nagħmel appuntament</code> means “make an appointment”</td></tr><tr><td>appuntament</td><td>appointment</td><td>Masculine loanword</td></tr><tr><td>mat-tabib</td><td>with the doctor; at the doctor&#39;s</td><td><code>ma&#39;</code> “with” + definite article, contracted in spelling</td></tr><tr><td>jekk</td><td>if</td><td>Used with <code>jogħġbok</code> in a polite request</td></tr><tr><td>jogħġbok</td><td>please; may it please you</td><td><code>jekk jogħġbok</code> as a whole means “please”</td></tr></tbody></table><h3 id="_3-maria-receptionist" tabindex="-1">3. Maria (Receptionist) <a class="header-anchor" href="#_3-maria-receptionist" aria-label="Permalink to &quot;3. Maria (Receptionist)&quot;">​</a></h3><p><strong>Malti:</strong> Għandek preferenza għal xi ġurnata?</p><p><strong>Translation:</strong> Do you have a preferred day?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għandek</td><td>you have</td><td>Second-person singular form of <code>għand</code></td></tr><tr><td>preferenza</td><td>preference; choice</td><td>Feminine noun</td></tr><tr><td>għal</td><td>for; regarding</td><td>Preposition</td></tr><tr><td>xi</td><td>some; any; a certain</td><td>Used here to ask which day</td></tr><tr><td>ġurnata</td><td>day</td><td>Feminine noun</td></tr></tbody></table><h3 id="_4-david-patient" tabindex="-1">4. David (Patient) <a class="header-anchor" href="#_4-david-patient" aria-label="Permalink to &quot;4. David (Patient)&quot;">​</a></h3><p><strong>Malti:</strong> Jekk jista&#39; jkun, għada filgħodu.</p><p><strong>Translation:</strong> If possible, tomorrow morning.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Jekk</td><td>if</td><td>Conjunction</td></tr><tr><td>jista&#39;</td><td>can; may</td><td>Third-person masculine singular</td></tr><tr><td>jkun</td><td>be; become</td><td>Subjunctive/subordinate form used in the expression <code>jekk jista&#39; jkun</code></td></tr><tr><td>għada</td><td>tomorrow</td><td>Time adverb</td></tr><tr><td>filgħodu</td><td>in the morning</td><td>Time expression</td></tr></tbody></table><h3 id="_5-maria-receptionist" tabindex="-1">5. Maria (Receptionist) <a class="header-anchor" href="#_5-maria-receptionist" aria-label="Permalink to &quot;5. Maria (Receptionist)&quot;">​</a></h3><p><strong>Malti:</strong> Għandna ħin fl-għaxra u nofs. Tajjeb għalik?</p><p><strong>Translation:</strong> We have an opening at half past ten. Does that work for you?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għandna</td><td>we have</td><td>First-person plural form of <code>għand</code></td></tr><tr><td>ħin</td><td>time; free time</td><td>Masculine noun</td></tr><tr><td>fl-għaxra</td><td>at ten</td><td>Contracted <code>f&#39;</code> “at” + <code>l-għaxra</code> “ten o&#39;clock”</td></tr><tr><td>u</td><td>and; past</td><td>Connects the hour and “half”</td></tr><tr><td>nofs</td><td>half</td><td>Used for half past the hour</td></tr><tr><td>Tajjeb</td><td>good; suitable</td><td>Masculine form; refers here to the time</td></tr><tr><td>għalik</td><td>for you</td><td><code>għal</code> “for” + <code>-ik</code> “you”</td></tr></tbody></table><h3 id="_6-david-patient" tabindex="-1">6. David (Patient) <a class="header-anchor" href="#_6-david-patient" aria-label="Permalink to &quot;6. David (Patient)&quot;">​</a></h3><p><strong>Malti:</strong> Iva, tajjeb ħafna. Għandi bżonn inġib xi dokumenti?</p><p><strong>Translation:</strong> Yes, that works very well. Do I need to bring any documents?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Iva</td><td>yes</td><td>Affirmative response</td></tr><tr><td>tajjeb</td><td>good; suitable</td><td>Masculine form</td></tr><tr><td>ħafna</td><td>very; a lot</td><td>Modifies <code>tajjeb</code> here: “very”</td></tr><tr><td>Għandi</td><td>I have</td><td>First-person singular form of <code>għand</code></td></tr><tr><td>bżonn</td><td>need</td><td><code>għandi bżonn</code> means “I need”</td></tr><tr><td>inġib</td><td>I bring; I take along</td><td>First-person singular form</td></tr><tr><td>xi</td><td>some; any</td><td>Can mean “what” in a question</td></tr><tr><td>dokumenti</td><td>documents</td><td>Plural of <code>dokument</code></td></tr></tbody></table><h3 id="_7-maria-receptionist" tabindex="-1">7. Maria (Receptionist) <a class="header-anchor" href="#_7-maria-receptionist" aria-label="Permalink to &quot;7. Maria (Receptionist)&quot;">​</a></h3><p><strong>Malti:</strong> Ġib il-karta tal-identità u l-karta tas-saħħa.</p><p><strong>Translation:</strong> Bring your identity card and health card.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Ġib</td><td>bring</td><td>Singular imperative</td></tr><tr><td>il-karta</td><td>the card; paper</td><td>Definite article <code>il-</code> + <code>karta</code></td></tr><tr><td>tal-identità</td><td>of identity; identity</td><td>Contracted form of <code>ta&#39; + l-identità</code></td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>il-karta</td><td>the card</td><td>Feminine noun with the definite article</td></tr><tr><td>tas-saħħa</td><td>of health; health</td><td>Contracted form of <code>ta&#39; + is-saħħa</code></td></tr></tbody></table><h3 id="_8-david-patient" tabindex="-1">8. David (Patient) <a class="header-anchor" href="#_8-david-patient" aria-label="Permalink to &quot;8. David (Patient)&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi. Narak għada.</p><p><strong>Translation:</strong> Thank you. See you tomorrow.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Grazzi</td><td>thank you</td><td>Common polite expression</td></tr><tr><td>Narak</td><td>I see you; see you</td><td><code>nara</code> “I see” + <code>-k</code> “you”</td></tr><tr><td>għada</td><td>tomorrow</td><td>Time adverb</td></tr></tbody></table><h2 id="useful-variations" tabindex="-1">Useful Variations <a class="header-anchor" href="#useful-variations" aria-label="Permalink to &quot;Useful Variations&quot;">​</a></h2><ul><li><code>filgħodu</code>: in the morning; <code>wara nofsinhar</code>: in the afternoon; <code>filgħaxija</code>: in the evening.</li><li><code>Għandi appuntament.</code>: I have an appointment.</li><li><code>Nista&#39; nbiddel il-ħin?</code>: Can I change the time?</li></ul>',46),r=[o];function i(s,l,h,c,p,g){return a(),e("div",null,r)}const b=t(n,[["render",i]]);export{u as __pageData,b as default};
